/**
 * ExpenseService
 *
 * Service for managing expenses derived from receipts
 * Specification: #{#exp1b} - Expenses Derived from Receipts
 * Authority: system
 * Priority: Critical
 *
 * Key Principles:
 * - Expenses are computed views, not separate database entities
 * - Each receipt generates exactly one expense (1:1 mapping)
 * - Deleting a receipt automatically removes the expense (CASCADE)
 * - Creating a receipt automatically makes it available as an expense
 */

import type { SupabaseClient } from '@supabase/supabase-js';

/**
 * Expense data structure derived from receipts
 * #{#umf1b} - Extended with matched_transaction_id for unmatched filter
 */
export interface Expense {
	receipt_id: string;
	merchant_name: string;
	total_amount: number | null; // null when OCR could not read the receipt amount
	transaction_date: string;
	receipt_image_path?: string;
	category_id: string | null;
	categorization_source: 'manual' | 'auto' | null;
	category_name?: string | null;
	category_color?: string | null;
	matched_transaction_id: string | null; // #{#umf1b} - Match status for reconciliation
	currency: string | null; // #{#fcr4a} - Original currency for display
	exchange_rate_to_cad: number | null; // #{#fcr4a} - Bank of Canada rate for estimated CAD
}

/**
 * The least a row must carry to be matched against a vendor rule: which receipt
 * it is, which merchant it names, and whether it already has a category.
 *
 * `Expense` satisfies this, and so does the Receipts page — which holds
 * `ReceiptRow[]` plus a separate category map rather than `Expense[]`. The rule
 * methods take this instead of a full `Expense` so both list pages can drive the
 * same code, rather than one of them assembling a throwaway `Expense`.
 */
export interface VendorRuleCandidate {
	receipt_id: string;
	merchant_name: string;
	category_id: string | null;
}

/**
 * Filter options for querying expenses
 */
export interface ExpenseFilters {
	startDate?: string;
	endDate?: string;
	categoryId?: string;
	merchantName?: string;
}

/**
 * Shape of a receipts row as returned by the expense query, including the
 * embedded expense_categories -> categories join (1:1 per receipt).
 */
interface ExpenseReceiptRow {
	id: string;
	merchant_name: string;
	total_amount: number | null; // receipts.total_amount is nullable (OCR may fail)
	transaction_date: string;
	receipt_image_path?: string;
	matched_transaction_id: string | null;
	currency: string | null;
	exchange_rate_to_cad: number | null;
	expense_categories: {
		category_id: string | null;
		categorization_source: 'manual' | 'auto' | null;
		categories: {
			name: string | null;
			color: string | null;
		} | null;
	} | null;
}

/**
 * Re-shapes a PostgREST embedded-join result to its real runtime shape.
 *
 * The untyped client infers to-one embeds (`expense_categories`, `categories`) as
