import { toISODateString } from './dateConversion';

export interface ManualReceiptForm {
	merchant_name: string;
	total_amount: string;
	transaction_date: string;
}

/**
 * A fresh manual-receipt form: empty merchant and amount, date defaulted to
 * today (local). Used both for the initial form state and to reset the form
 * after a successful create.
 */
export function newManualReceiptForm(): ManualReceiptForm {
	return {
		merchant_name: '',
		total_amount: '',
		transaction_date: toISODateString(new Date())
	};
}

export interface ManualReceiptValues {
	merchant_name: string;
	total_amount: number;
	transaction_date: string;
}

export type ManualReceiptField = 'merchant_name' | 'total_amount';

export type ManualReceiptValidation =
	| { ok: true; value: ManualReceiptValues }
	| { ok: false; field: ManualReceiptField; message: string };

export function validateManualReceipt(form: ManualReceiptForm): ManualReceiptValidation {
	const merchant_name = form.merchant_name.trim();
	if (merchant_name === '') {
		return { ok: false, field: 'merchant_name', message: 'Enter a merchant name.' };
	}

	const total_amount = parseFloat(form.total_amount);
	if (Number.isNaN(total_amount) || total_amount <= 0) {
		return { ok: false, field: 'total_amount', message: 'Receipt amount should greater than 0.00' };
	}

	return {
		ok: true,
		value: {
			merchant_name,
			total_amount,
			transaction_date: form.transaction_date
		}
	};
}

