describe('Manual Date Edit Skips Suspicious Flag (v1.3.0)', () => {
	it('should set suspicious_date to false when user edits date to a recent date', async () => {
		const mockUpdatedReceipt = makeReceiptRow({
			id: 'receipt-5',
			user_id: 'test-user-id',
			receipt_image_path: 'receipts/test.jpg',
			transaction_date: '2025-12-07',
			total_amount: 50.0,
			tax: 5.0,
			merchant_name: 'Test Store',
			currency: 'USD',
			created_at: '2025-12-09T12:00:00Z',
			suspicious_date: false
		});

		mockSingle.mockResolvedValue({ data: mockUpdatedReceipt, error: null });

		const service = new ReceiptService(supabase);
		await service.update('receipt-5', {
			transaction_date: '2025-12-07'
		});

		// Must NOT call isSuspiciousDate — user manually set the date
		expect(isSuspiciousDate).not.toHaveBeenCalled();
		// Must send suspicious_date: false in the update patch
		expect(mockUpdate).toHaveBeenCalledWith(expect.objectContaining({ suspicious_date: false }));
	});

	it('should set suspicious_date to false even when user sets an old date (>42 days)', async () => {
		// User intentionally sets old date — should NOT be re-flagged
		const mockUpdatedReceipt = makeReceiptRow({
			id: 'receipt-6',
			user_id: 'test-user-id',
			receipt_image_path: 'receipts/test.jpg',
			transaction_date: '2025-08-15', // >42 days old
			total_amount: 50.0,
			tax: 5.0,
			merchant_name: 'Test Store',
			currency: 'USD',
			created_at: '2025-12-09T12:00:00Z',
			suspicious_date: false
		});

		mockSingle.mockResolvedValue({ data: mockUpdatedReceipt, error: null });

		const service = new ReceiptService(supabase);
		await service.update('receipt-6', {
			transaction_date: '2025-08-15'
		});

		// Must NOT call isSuspiciousDate — user deliberately chose this date
		expect(isSuspiciousDate).not.toHaveBeenCalled();
		// Must send suspicious_date: false (not re-flagged)
		expect(mockUpdate).toHaveBeenCalledWith(expect.objectContaining({ suspicious_date: false }));
	});

	it('should set suspicious_date to false even when user sets a future date', async () => {
		// User intentionally sets future date — should NOT be flagged
		const mockUpdatedReceipt = makeReceiptRow({
			id: 'receipt-7',
			user_id: 'test-user-id',
			receipt_image_path: 'receipts/test.jpg',
			transaction_date: '2026-06-15', // Future date
			total_amount: 50.0,
			tax: 5.0,
			merchant_name: 'Test Store',
			currency: 'USD',
			created_at: '2025-12-09T12:00:00Z',
			suspicious_date: false
		});

