// `update()` owns the clear-on-save rule; callers do not get a vote. These two
// pin that, because it is what makes the `suspicious_date` line in the Receipts
// page's patch literal (`receipts/+page.svelte:227`) dead code — the value it
// passes under the comment "Preserve confirmed suspicious_date status" is
// overwritten here before it reaches the database. If the forcing below is ever
// removed, these go red and the three pages stop agreeing silently.
describe('suspicious_date is decided by update(), not by its caller', () => {
	it('overrides a caller that explicitly asks to keep the flag set', async () => {
		mockSingle.mockResolvedValue({
			data: makeReceiptRow({ id: 'receipt-keep', suspicious_date: false }),
			error: null
		});

		const service = new ReceiptService(supabase);
		await service.update('receipt-keep', {
			transaction_date: '2026-02-15',
			suspicious_date: true // caller asks to preserve the flag
		});

		expect(mockUpdate).toHaveBeenCalledWith(expect.objectContaining({ suspicious_date: false }));
	});

	it('triggers on the presence of transaction_date, not on its value', async () => {
		// A null date still clears the flag: the guard is `'transaction_date' in
		// safePatch`, which tests key presence. Both pages always send the key.
		mockSingle.mockResolvedValue({
			data: makeReceiptRow({ id: 'receipt-null-date', suspicious_date: false }),
			error: null
		});

		const service = new ReceiptService(supabase);
		await service.update('receipt-null-date', {
			transaction_date: null,
			suspicious_date: true
		});

		expect(mockUpdate).toHaveBeenCalledWith(expect.objectContaining({ suspicious_date: false }));
	});
});

