/**
 * Fetch one receipt in full.
 *
 * Exists so a caller holding only a partial view of a receipt — the Expenses
 * page holds an `Expense`, which carries neither tax nor card details — can get
 * the real row before editing it. Assembling a `ReceiptRow`-shaped literal from
 * a projection and saving it writes the missing fields away; that was a live
 * data-loss bug on the Expenses page.
 */
async getById(id: string): Promise<ReceiptRow> {
	return withRetry(async () => {
		const { data, error } = await this.supabase
			.from('receipts')
			.select('*')
			.eq('id', id)
			.single();
		if (error) throw error;
		return data as ReceiptRow;
	});
}

