/**
 * Fetch the real receipt before opening the modal.
 *
 * This used to assemble a `ReceiptRow`-shaped literal from the `Expense`,
 * filling everything `Expense` does not carry with `null`/`false` — and
 * `handleReceiptSave` then wrote those placeholders back, so saving an
 * unedited receipt from this page erased its tax, card details and
 * reconciliation match. Fetching the row removes the whole class: every
 * column added to `receipts` from now on is carried automatically.
 */
async function openReceiptEditModal(expense: Expense) {
	error = null;
	try {
		editingReceipt = await receiptService.getById(expense.receipt_id);
		editingExpense = expense;
		showEditModal = true;
	} catch (err) {
		error = err instanceof Error ? err.message : 'Failed to load receipt';
	}
}

