import { describe, it, expect } from 'vitest';
import { buildReceiptPatch, normalizeNote } from './receiptPatch';
import { makeReceiptRow } from '$lib/tests/builders/rowBuilders';

/**
 * The Receipts, Reconciliation and Expenses pages each used to hand-write the
 * patch they send to `ReceiptService.update`. Three lists that had to agree, and
 * did not: the Receipts one carried `suspicious_date`, Reconciliation's did not.
 * These tests pin the single replacement.
 */
describe('buildReceiptPatch', () => {
	it('carries every field the edit modal can change', () => {
		const patch = buildReceiptPatch(
			makeReceiptRow({
				merchant_name: 'Costco',
				transaction_date: '2026-02-15',
				total_amount: 120.5,
				tax: 15.6,
				currency: 'USD',
				exchange_rate_to_cad: 1.37,
				credit_card_name: 'Visa',
				credit_card_last_4: '4242',
				notes: "Sam's birthday gift"
			})
		);

		expect(patch).toEqual({
			merchant_name: 'Costco',
			transaction_date: '2026-02-15',
			total_amount: 120.5,
			tax: 15.6,
			currency: 'USD',
			exchange_rate_to_cad: 1.37,
			credit_card_name: 'Visa',
			credit_card_last_4: '4242',
			notes: "Sam's birthday gift"
		});
	});

	it('omits suspicious_date, which update() decides for itself', () => {
		// `ReceiptService.update` forces the flag to false whenever transaction_date
		// is present. A page-level copy of that rule is dead code — it was, in the
		// Receipts patch, under a comment claiming the opposite.
		const patch = buildReceiptPatch(makeReceiptRow({ suspicious_date: true }));

		expect(patch).not.toHaveProperty('suspicious_date');
	});

	it('omits identity columns and fields the modal cannot edit', () => {
		const patch = buildReceiptPatch(makeReceiptRow());

		for (const key of [
			'id',
			'user_id',
			'created_at',
			'receipt_image_path',
			'matched_transaction_id',
			'split_group_id',
			'original_filename'
		]) {
			expect(patch).not.toHaveProperty(key);
		}
	});

	it('normalizes a whitespace-only note to null', () => {
		// Absent is NULL, never the empty string — otherwise "no note" has two
		// spellings and every read has to handle both.
		expect(buildReceiptPatch(makeReceiptRow({ notes: '   \n  ' })).notes).toBeNull();
	});

	it('trims surrounding whitespace but preserves a note's internal newlines', () => {
		expect(buildReceiptPatch(makeReceiptRow({ notes: '  line one\nline two  ' })).notes).toBe(
			'line one\nline two'
		);
	});
});

describe('normalizeNote', () => {
	it('maps every empty spelling to null', () => {
		expect(normalizeNote(null)).toBeNull();
		expect(normalizeNote('')).toBeNull();
		expect(normalizeNote('\t \n')).toBeNull();
	});

	it('returns the trimmed text otherwise', () => {
		expect(normalizeNote('  kept  ')).toBe('kept');
	});
});

