import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render } from 'vitest-browser-svelte';
import { makeExpense, makeReceiptRow } from './builders/rowBuilders';
import {
	pageStore,
	supabaseMock,
	ExpenseServiceStub,
	CategoryServiceStub,
	ReceiptServiceStub,
	setExpenses,
	setReceipts,
	setSession,
	fakeSession,
	resetHarness
} from './harness/appMocks';

// Same module boundaries as expenses-page.svelte.spec.ts. See harness/appMocks.ts.
vi.mock('$app/stores', () => ({ page: pageStore }));
vi.mock('$lib/supabaseClient', () => ({ supabase: supabaseMock }));
vi.mock('$app/navigation', () => ({ goto: () => {}, replaceState: () => {} }));
vi.mock('$app/paths', () => ({ resolve: (p: string) => p }));
vi.mock('$lib/utils/signedUrl', () => ({
	getSignedReceiptUrls: async () => ({}),
	getSignedReceiptUrl: async () => null
}));
vi.mock('$lib/utils/familyUtils', () => ({ getDefaultFamilyId: async () => 'family-1' }));
vi.mock('$lib/services/ExpenseService', () => ({ ExpenseService: ExpenseServiceStub }));
vi.mock('$lib/services/CategoryService', () => ({ CategoryService: CategoryServiceStub }));
vi.mock('$lib/services/ReceiptService', () => ({ ReceiptService: ReceiptServiceStub }));

import ExpensesPage from '../../routes/expenses/+page.svelte';

/**
 * Behavior tests for the expenses page → ReceiptEditModal integration
 *
 * Replaces the source-introspection expenses-page-receipt-modal.spec.ts, which
 * regex'd the page for the row-click handler, modal props, save/close wiring, etc.
 * The real, previously-uncovered behavior is: clicking an expense row opens the
 * modal, and clicking the interactive Category cell does not. The modal's own
 * save/close and the Notification banner are covered by their component/service
 * tests. Built on the route-render harness (harness/appMocks.ts).
 */
describe('expenses page → receipt edit modal', () => {
	beforeEach(resetHarness);

	it('opens the ReceiptEditModal when an expense row is clicked', async () => {
		setSession(fakeSession());
		// The page fetches the real receipt before opening — both builders default
		// to id 'receipt-1', so this is the row behind that expense.
		setReceipts([makeReceiptRow()]);
		setExpenses([makeExpense({ merchant_name: 'Clickable Merchant' })]);

		const screen = render(ExpensesPage);

		const row = screen.getByText('Clickable Merchant');
		await expect.element(row).toBeVisible();
		await expect.element(screen.getByRole('dialog')).not.toBeInTheDocument();

		await row.click();

		await expect.element(screen.getByRole('dialog')).toBeVisible();
		await expect.element(screen.getByText('Edit Receipt')).toBeVisible();
	});

	it('preserves fields the Expense projection does not carry when saving unchanged', async () => {
		// The Expenses page opens the modal from an `Expense`, which carries neither
		// tax nor card details. Saving must not therefore write them away — and it
		// must not drop the reconciliation match, which `Expense` DOES carry.
		const update = vi.spyOn(ReceiptServiceStub.prototype, 'update');

		setSession(fakeSession());
		setReceipts([
			makeReceiptRow({
				id: 'receipt-1',
				merchant_name: 'Costco',
				tax: 5.53,
				credit_card_name: 'Visa',
				credit_card_last_4: '4242',
				matched_transaction_id: 'txn-999'
			})
		]);
		setExpenses([
			makeExpense({
				receipt_id: 'receipt-1',
				merchant_name: 'Costco',
				matched_transaction_id: 'txn-999'
			})
		]);

		const screen = render(ExpensesPage);

		await screen.getByText('Costco').click();
		await expect.element(screen.getByRole('dialog')).toBeVisible();

		// Save without editing anything.
		await screen.getByRole('button', { name: 'Save Changes' }).click();

		expect(update).toHaveBeenCalledWith(
			'receipt-1',
			expect.objectContaining({
				tax: 5.53,
				credit_card_name: 'Visa',
				credit_card_last_4: '4242',
				matched_transaction_id: 'txn-999'
			})
		);
	});

	it('does not open the modal when the interactive Category cell is clicked', async () => {
		setSession(fakeSession());
		setExpenses([makeExpense({ merchant_name: 'Clickable Merchant' })]);

		const screen = render(ExpensesPage);

		// The category column is marked interactive, so its click opens the dropdown,
		// not the row's edit modal.
		await screen.getByRole('button', { name: 'Category' }).click();

		await expect.element(screen.getByRole('dialog')).not.toBeInTheDocument();
	});
});

