import { describe, it, expect } from 'vitest';
import { noteLengthError, notePreview, NOTE_MAX_LENGTH } from './note';

describe('noteLengthError', () => {
	it('accepts a note at exactly the limit', () => {
		expect(noteLengthError('x'.repeat(NOTE_MAX_LENGTH))).toBeNull();
	});

	it('accepts an absent note', () => {
		expect(noteLengthError(null)).toBeNull();
		expect(noteLengthError(undefined)).toBeNull();
	});

	it('states the overage, not the limit, so the message is actionable', () => {
		expect(noteLengthError('x'.repeat(NOTE_MAX_LENGTH + 1))).toMatch(/1 character over/);
		expect(noteLengthError('x'.repeat(NOTE_MAX_LENGTH + 37))).toMatch(/37 characters over/);
	});
});

describe('notePreview', () => {
	it('collapses newlines to spaces so a multi-line note fits one row', () => {
		expect(notePreview('line one\nline two')).toBe('line one line two');
	});

	it('collapses a run of whitespace to a single space', () => {
		expect(notePreview('spaced   \n\n  out')).toBe('spaced out');
	});

	it('trims, and maps an empty or whitespace-only note to null', () => {
		expect(notePreview('  kept  ')).toBe('kept');
		expect(notePreview('   ')).toBeNull();
		expect(notePreview('')).toBeNull();
		expect(notePreview(null)).toBeNull();
	});
});

