export function noteLengthError(notes: string | null | undefined): string | null {
	const over = (notes?.length ?? 0) - NOTE_MAX_LENGTH;
	if (over <= 0) return null;
	return `Note is ${over} character${over === 1 ? '' : 's'} over the ${NOTE_MAX_LENGTH} limit. Please shorten it.`;
}

/**
 * The single-line form shown under a merchant name in the Receipts and Expenses
 * tables, or `null` when there is nothing to show.
 *
 * A stored Note may contain newlines; a table row is one line. Collapsing runs of
 * whitespace here rather than relying on CSS keeps the `title` tooltip and the
 * visible text in agreement, and stops a note that opens with a blank line from
 * rendering as an empty preview.
 *
 * Truncation is deliberately NOT done here — the visible width is a CSS concern
 * (`truncate`), so the preview adapts to the column instead of guessing at a
 * character budget.
 */
export function notePreview(notes: string | null | undefined): string | null {
	const collapsed = notes?.replace(/\s+/g, ' ').trim();
	return collapsed ? collapsed : null;
}

