/**
 * The ceiling a Note is allowed to reach, mirrored by the
 * `receipts_notes_length` CHECK constraint. The database is the real limit;
 * this is what lets the modal say so before a save round-trips and fails.
 *
 * Counting differs slightly on each side and that is safe: JavaScript's
 * `.length` counts UTF-16 units while Postgres `char_length` counts characters,
 * so an emoji is 2 here and 1 there. The client therefore only ever
 * over-counts, and can never admit something the constraint would reject.
 */
export const NOTE_MAX_LENGTH = 1024;

/** Where the counter appears. Silent until a note is long enough to be at risk. */
export const NOTE_COUNTER_FROM = 900;

/**
 * The message shown when a note is too long, or `null` when it fits.
 *
 * Deliberately states the overage rather than the limit: "you are 37 characters
 * over" is directly actionable, where "max 1024" leaves the person counting.
 * There is no `maxlength` on the textarea, precisely so an over-long paste
 * arrives whole and its author decides what to cut — a browser truncation would
 * be silent, and silent truncation of text someone wrote is not detectable after
 * the fact.
 */
export function noteLengthError(notes: string | null | undefined): string | null {
	const over = (notes?.length ?? 0) - NOTE_MAX_LENGTH;
	if (over <= 0) return null;
	return `Note is ${over} character${over === 1 ? '' : 's'} over the ${NOTE_MAX_LENGTH} limit. Please shorten it.`;
}

