43	export class ReceiptService {
44		private supabase: SupabaseClient;
45	
46		constructor(supabase: SupabaseClient) {
47			this.supabase = supabase;
48		}
49	
50		/**
51		 * Call the server-side OCR API to extract receipt data
52		 */
53		private async extractOcrData(fileUrl: string, mimeType: string): Promise<ReceiptExtract | null> {
54			try {
55				const response = await fetch('/api/ocr/extract', {
56					method: 'POST',
57					headers: {
58						'Content-Type': 'application/json'
59					},
60					body: JSON.stringify({ fileUrl, mimeType })
61				});
62	
63				if (!response.ok) {
64					const errorText = await response.text();
65					throw new Error(`OCR API error: ${response.status} - ${errorText}`);
66				}
67	
68				const result = await response.json();
69				return result.data;
70			} catch (e) {
71				console.error('OCR extraction failed:', e);
72				return null;
73			}
74		}
75	
76		async list(
77			sort: 'transaction_date' | 'merchant_name' | 'total_amount' = 'transaction_date',
78			direction: 'asc' | 'desc' = 'desc'
79		) {
80			return withRetry(async () => {
81				const user = (await this.supabase.auth.getUser()).data.user;
82				if (!user) throw new Error('Not authenticated');
83	
84				console.log('[ReceiptService] Fetching receipts for user:', user.id);
85	
86				// Check family memberships for debugging
87				const { data: familyMemberships, error: fmError } = await this.supabase
88					.from('family_members')
89					.select('*')
90					.eq('user_id', user.id);
91				console.log('[ReceiptService] Family memberships:', familyMemberships, fmError);
92	
93				// Don't filter by user_id - let RLS policies handle access based on family membership
94				// This allows family members to see each other's receipts
95				const { data, error } = await this.supabase
